/** Repository of the "countries" table: reads and writes rows, and decides nothing. */
import type { ClientSession } from 'mongoose'
import { Country } from './entity.js'
import { plain, refusal, type Db } from '../database.js'
import type { Stored } from '../models.js'
import type { CursorPage } from '../paging.js'

/** Where countries rows are kept. Services depend only on this interface. */
export interface CountryRepository {
  findByDocumentId(_id: string): Promise<Country | null>
  list(after?: unknown[] | null, limit?: number): Promise<CursorPage<Country>>
  findById(id: number): Promise<Country | null>
  insert(entity: Country): Promise<Country>
  update(entity: Country): Promise<Country>
  delete(entity: Country): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Country): unknown[] {
  return [row._id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The values each entity was read with, by the stored names of its fields: a change writes only those that differ. */
const loaded = new WeakMap<Country, Record<string, string>>()

/** The fields of an entity a change may write. */
function changeable(entity: Country): Stored {
  return {
    id: entity.id,
    name: entity.name,
  }
}

/** The same fields as text, to compare them later. */
const snapshot = (entity: Country): Record<string, string> =>
  Object.fromEntries(Object.entries(changeable(entity)).map(([name, value]) => [name, JSON.stringify(value ?? null)]))

/** The Country of a document; a field it does not have is null. */
function toEntity(document: Stored): Country {
  const entity = Object.assign(new Country(), {
    _id: (plain(document._id) ?? null) as string,
    id: (plain(document.id) ?? null) as number,
    name: (plain(document.name) ?? null) as string,
  })
  loaded.set(entity, snapshot(entity))
  return entity
}

/** The fields of a new document; those left empty are not stored, and take their default. */
function storedValues(entity: Country): Stored {
  const values: Stored = {
    _id: entity._id,
    id: entity.id,
    name: entity.name,
  }
  return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined && value !== null))
}

/** What a change writes and what it removes: only the fields that are not as they were read. */
function changesOf(entity: Country): { $set: Stored; $unset: Stored } {
  const before = loaded.get(entity)
  const $set: Stored = {}
  const $unset: Stored = {}
  for (const [name, value] of Object.entries(changeable(entity))) {
    if (before?.[name] === JSON.stringify(value ?? null)) continue
    if (value === undefined || value === null) $unset[name] = ''
    else $set[name] = value
  }
  return { $set, $unset }
}

/** Keeps countries documents in the database, through Mongoose. Queries run in the session it was given. */
export class MongoCountryRepository implements CountryRepository {
  constructor(
    private readonly db: Db,
    private readonly session: ClientSession | null = null,
  ) {}

  /** The row with this primary key, or null. */
  async findByDocumentId(_id: string): Promise<Country | null> {
    const foundDocument = await this.db.models.countries.findOne({ _id }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** At most `limit` rows after the key `after`, by primary key, and the key to read the next page from. */
  async list(after: unknown[] | null = null, limit: number = 50): Promise<CursorPage<Country>> {
    const filter = after === null ? {} : { _id: { $gt: after[0] } }
    const rows = (await this.db.models.countries.find(filter).sort({ _id: 1 }).limit(limit + 1).session(this.session).lean<Stored[]>()).map(toEntity)
    const items = rows.slice(0, limit)
    const last = items[items.length - 1]
    return { items, next: rows.length > limit ? [last._id] : null }
  }

  /** The row with this id, or null. */
  async findById(id: number): Promise<Country | null> {
    const foundDocument = await this.db.models.countries.findOne({ id }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Country): Promise<Country> {
    try {
      const [document] = await this.db.models.countries.create([storedValues(entity)], { session: this.session ?? undefined })
      const stored = toEntity(document.toObject() as Stored)
      Object.assign(entity, stored)
      loaded.set(entity, loaded.get(stored)!)
      return entity
    } catch (error) {
      throw refusal('Country', error)
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Country): Promise<Country> {
    try {
      await this.db.models.countries.updateOne({ _id: entity._id }, changesOf(entity), { session: this.session ?? undefined, runValidators: true, timestamps: false })
    } catch (error) {
      throw refusal('Country', error)
    }
    loaded.set(entity, snapshot(entity))
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Country): Promise<void> {
    try {
      await this.db.models.countries.deleteOne({ _id: entity._id }).session(this.session)
    } catch (error) {
      throw refusal('Country', error)
    }
  }
}

/** Keeps countries rows in memory, for tests and for trying the services without a database. */
export class MemoryCountryRepository implements CountryRepository {
  private readonly rows = new Map<string, Country>()

  private visible(): Country[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findByDocumentId(_id: string): Promise<Country | null> {
    return this.visible().find((row) => row._id === _id) ?? null
  }

  /** At most `limit` rows after the key `after`, by primary key, and the key to read the next page from. */
  async list(after: unknown[] | null = null, limit: number = 50): Promise<CursorPage<Country>> {
    const rows = this.visible().filter((row) => after === null || compareKeys(keyOf(row), after) > 0)
    const items = rows.slice(0, limit)
    return { items, next: rows.length > limit ? keyOf(items[items.length - 1]) : null }
  }

  /** The row with this id, or null. */
  async findById(id: number): Promise<Country | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Country): Promise<Country> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Country): Promise<Country> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Country): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }
}

