/** Operations on countries: what each one checks before it writes. */
import type { CountryCreate, CountryRead, CountryUpdate } from './dtos.js'
import { Country } from './entity.js'
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { CursorPage } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['_id', 'id', 'name'])

/** Operations on countries. Each write runs in its own transaction. */
export class CountryService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "countries" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Country | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Country' })
    if (!creating) for (const name of Object.keys(values)) if (['_id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values._id
      if (value == null) {
        if (creating || '_id' in values) errors.push({ field: '_id', message: 'is required' })
      }
    }
    {
      const value = values.id
      if (value == null) {
        if (creating || 'id' in values) errors.push({ field: 'id', message: 'is required' })
      }
    }
    {
      const value = values.name
      if (value == null) {
        if (creating || 'name' in values) errors.push({ field: 'name', message: 'is required' })
      }
    }
    if (errors.length > 0) throw new ValidationFailedError('Country', errors)
  }

  /** Values that must be unique are not taken by another row. */
  private async checkUnique(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Country | null): Promise<void> {
    {
      const id = ('id' in values ? values.id : current?.id) as number | null | undefined
      if (id != null) {
        const other = await uow.countries.findById(id)
        if (other !== null && (current === null || other._id !== current._id))
          throw new ConflictError('Country', 'id is already taken', ['id'])
      }
    }
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Country | null): Promise<void> {
    await this.validate(uow, values, current)
    await this.checkUnique(uow, values, current)
  }

  /** The Country with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, _id: string): Promise<Country> {
    const entity = await uow.countries.findByDocumentId(_id)
    if (entity === null) throw new NotFoundError('Country', _id)
    return entity
  }

  /** The Country as services return it. */
  private static read(entity: Country): CountryRead {
    return { _id: entity._id, id: entity.id, name: entity.name }
  }

  /** Stores a new Country after checking it. */
  async createCountry(data: CountryCreate): Promise<CountryRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.countries.insert(Object.assign(new Country(), values))
      return CountryService.read(created)
    })
  }

  /** The Country with this key; NotFoundError when there is none. */
  async getCountry(_id: string): Promise<CountryRead> {
    return CountryService.read(await this.find(this.uow, _id))
  }

  /** A page of countries after the key `after`, by primary key. */
  async listCountries(after: unknown[] | null = null, limit = 50): Promise<CursorPage<CountryRead>> {
    const page = await this.uow.countries.list(after, limit)
    return { ...page, items: page.items.map((entity) => CountryService.read(entity)) }
  }

  /** Changes the given values of a Country. */
  async updateCountry(_id: string, data: CountryUpdate): Promise<CountryRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, _id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.countries.update(current)
      return CountryService.read(updated)
    })
  }

  /** Deletes a Country. */
  async deleteCountry(_id: string): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, _id)
      await uow.countries.delete(current)
    })
  }

  /** The Country with this id, or null. */
  async findCountryById(id: number): Promise<CountryRead | null> {
    const entity = await this.uow.countries.findById(id)
    return entity === null ? null : CountryService.read(entity)
  }
}

