/** The collections of the database, as Mongoose models. They reflect it: Mongoose never creates collections or indexes with them. */
import { Schema, type Connection, type Model } from 'mongoose'

/** A document as the driver gives it, by the stored names of its fields */
export type Stored = Record<string, unknown>

/** The model of every collection */
export interface Models {
  customers: Model<Stored>
  products: Model<Stored>
  orders: Model<Stored>
  countries: Model<Stored>
}

/** Defines the model of every collection on `connection`. */
export function defineModels(connection: Connection): Models {
  /** The 'customers' collection. */
  const customers = new Schema(
    {
      email: { type: String, required: true, maxlength: 120 },
      name: { type: String, required: true, minlength: 2 },
      passwordHash: String,
      active: { type: Boolean, default: true },
      level: { type: String, enum: ['basic', 'gold'], default: 'basic' },
      address: new Schema({ street: { type: String, required: true }, city: { type: String, required: true }, 'zip code': String, location: new Schema({ type: { type: String, enum: ['Point'] }, coordinates: { type: [Number], default: undefined } }, { _id: false, strict: false, minimize: false }) }, { _id: false, strict: false, minimize: false }),
      tags: { type: [String], default: undefined },
      preferences: new Schema({ theme: { type: String, default: 'light' }, newsletter: Boolean }, { _id: false, strict: false, minimize: false }),
      extra: Schema.Types.Mixed,
      deletedAt: Date,
      createdAt: { type: Date, default: () => new Date() },
      updatedAt: { type: Date, default: () => new Date() },
    },
    { collection: 'customers', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )
  customers.index({ email: 1 }, { unique: true })

  /** The 'products' collection. */
  const products = new Schema(
    {
      sku: { type: String, required: true },
      title: { type: String, required: true },
      price: { type: Schema.Types.Decimal128, required: true },
      stock: { type: Number, min: 0, default: 0 },
      reference: Schema.Types.UUID,
      picture: Buffer,
      related: { type: [Schema.Types.ObjectId], default: undefined },
    },
    { collection: 'products', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )
  products.index({ sku: 1 }, { unique: true })
  products.index({ title: 1 })

  /** The 'orders' collection. */
  const orders = new Schema(
    {
      number: { type: Number, required: true },
      year: { type: Number, required: true },
      customer: { type: Schema.Types.ObjectId, required: true },
      lines: { type: [new Schema({ product: { type: Schema.Types.ObjectId, required: true }, quantity: { type: Number, required: true, min: 1 }, price: { type: Schema.Types.Decimal128, required: true }, status: { type: String, enum: ['pending', 'sent'], default: 'pending' } }, { strict: false, minimize: false })], default: undefined, required: true },
      notes: { type: [new Schema({ text: String, at: Date }, { strict: false, minimize: false })], default: undefined },
      placedAt: { type: Date, default: () => new Date() },
    },
    { collection: 'orders', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )
  orders.index({ year: 1, number: 1 }, { unique: true })
  orders.index({ customer: 1 })

  /** The 'countries' collection. */
  const countries = new Schema(
    {
      _id: String,
      id: { type: Number, required: true },
      name: { type: String, required: true },
    },
    { collection: 'countries', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )
  countries.index({ id: 1 }, { unique: true })

  return {
    customers: connection.model<Stored>('Customer', customers as unknown as Schema<Stored>),
    products: connection.model<Stored>('Product', products as unknown as Schema<Stored>),
    orders: connection.model<Stored>('Order', orders as unknown as Schema<Stored>),
    countries: connection.model<Stored>('Country', countries as unknown as Schema<Stored>),
  }
}

