/** Repository of the "orders" table: reads and writes rows, and decides nothing. */
import type { ClientSession } from 'mongoose'
import { randomBytes } from 'node:crypto'
import { isObjectId, plain, refusal, type Db } from '../database.js'
import type { Stored } from '../models.js'
import { Order } from './entity.js'
import type { CursorPage } from '../paging.js'

/** Where orders rows are kept. Services depend only on this interface. */
export interface OrderRepository {
  findById(id: string): Promise<Order | null>
  list(after?: unknown[] | null, limit?: number): Promise<CursorPage<Order>>
  findByYearAndNumber(year: number, number: number): Promise<Order | null>
  listByCustomer(customer: string): Promise<Order[]>
  insert(entity: Order): Promise<Order>
  update(entity: Order): Promise<Order>
  delete(entity: Order): Promise<void>
  addLine(id: string, line: { _id?: string | null; product: string; quantity: number; price: string; status?: string | null }): Promise<Order | null>
  removeLine(id: string, lineId: string): Promise<Order | null>
  addNote(id: string, note: { _id?: string | null; text?: string | null; at?: Date | null }): Promise<Order | null>
  removeNote(id: string, noteId: string): Promise<Order | null>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Order): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The values each entity was read with, by the stored names of its fields: a change writes only those that differ. */
const loaded = new WeakMap<Order, Record<string, string>>()

/** The fields of an entity a change may write. */
function changeable(entity: Order): Stored {
  return {
    number: entity.number,
    year: entity.year,
    customer: entity.customer,
    lines: entity.lines,
    notes: entity.notes,
  }
}

/** The same fields as text, to compare them later. */
const snapshot = (entity: Order): Record<string, string> =>
  Object.fromEntries(Object.entries(changeable(entity)).map(([name, value]) => [name, JSON.stringify(value ?? null)]))

/** The Order of a document; a field it does not have is null. */
function toEntity(document: Stored): Order {
  const entity = Object.assign(new Order(), {
    id: (plain(document._id) ?? null) as string,
    number: (plain(document.number) ?? null) as number,
    year: (plain(document.year) ?? null) as number,
    customer: (plain(document.customer) ?? null) as string,
    lines: (plain(document.lines) ?? null) as { _id?: string | null; product: string; quantity: number; price: string; status?: string | null }[],
    notes: (plain(document.notes) ?? null) as { _id?: string | null; text?: string | null; at?: Date | null }[] | null,
    placedAt: (plain(document.placedAt) ?? null) as Date | null,
  })
  loaded.set(entity, snapshot(entity))
  return entity
}

/** The fields of a new document; those left empty are not stored, and take their default. */
function storedValues(entity: Order): Stored {
  const values: Stored = {
    _id: entity.id,
    number: entity.number,
    year: entity.year,
    customer: entity.customer,
    lines: entity.lines,
    notes: entity.notes,
    placedAt: entity.placedAt,
  }
  return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined && value !== null))
}

/** What a change writes and what it removes: only the fields that are not as they were read. */
function changesOf(entity: Order): { $set: Stored; $unset: Stored } {
  const before = loaded.get(entity)
  const $set: Stored = {}
  const $unset: Stored = {}
  for (const [name, value] of Object.entries(changeable(entity))) {
    if (before?.[name] === JSON.stringify(value ?? null)) continue
    if (value === undefined || value === null) $unset[name] = ''
    else $set[name] = value
  }
  return { $set, $unset }
}

/** Keeps orders documents in the database, through Mongoose. Queries run in the session it was given. */
export class MongoOrderRepository implements OrderRepository {
  constructor(
    private readonly db: Db,
    private readonly session: ClientSession | null = null,
  ) {}

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Order | null> {
    if (!isObjectId(id)) return null
    const foundDocument = await this.db.models.orders.findOne({ _id: id }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** At most `limit` rows after the key `after`, by primary key, and the key to read the next page from. */
  async list(after: unknown[] | null = null, limit: number = 50): Promise<CursorPage<Order>> {
    const filter = after === null ? {} : { _id: { $gt: after[0] } }
    const rows = (await this.db.models.orders.find(filter).sort({ _id: 1 }).limit(limit + 1).session(this.session).lean<Stored[]>()).map(toEntity)
    const items = rows.slice(0, limit)
    const last = items[items.length - 1]
    return { items, next: rows.length > limit ? [last.id] : null }
  }

  /** The row with this year and number, or null. */
  async findByYearAndNumber(year: number, number: number): Promise<Order | null> {
    const foundDocument = await this.db.models.orders.findOne({ year, number }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** Rows with this customer, by primary key. */
  async listByCustomer(customer: string): Promise<Order[]> {
    if (!isObjectId(customer)) return []
    return (await this.db.models.orders.find({ customer }).sort({ _id: 1 }).session(this.session).lean<Stored[]>()).map(toEntity)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Order): Promise<Order> {
    try {
      const [document] = await this.db.models.orders.create([storedValues(entity)], { session: this.session ?? undefined })
      const stored = toEntity(document.toObject() as Stored)
      Object.assign(entity, stored)
      loaded.set(entity, loaded.get(stored)!)
      return entity
    } catch (error) {
      throw refusal('Order', error)
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Order): Promise<Order> {
    try {
      await this.db.models.orders.updateOne({ _id: entity.id }, changesOf(entity), { session: this.session ?? undefined, runValidators: true, timestamps: false })
    } catch (error) {
      throw refusal('Order', error)
    }
    loaded.set(entity, snapshot(entity))
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Order): Promise<void> {
    try {
      await this.db.models.orders.deleteOne({ _id: entity.id }).session(this.session)
    } catch (error) {
      throw refusal('Order', error)
    }
  }

  /** Adds an item to lines, and returns the row as it is then, or null when there is none. */
  async addLine(id: string, line: { _id?: string | null; product: string; quantity: number; price: string; status?: string | null }): Promise<Order | null> {
    if (!isObjectId(id)) return null
    let changed: Stored | null
    try {
      changed = await this.db.models.orders
        .findOneAndUpdate({ _id: id }, { $push: { lines: line } }, { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Order', error)
    }
    return changed === null ? null : toEntity(changed)
  }

  /** Removes an item from lines, and returns the row as it is then, or null when there is none. */
  async removeLine(id: string, lineId: string): Promise<Order | null> {
    if (!isObjectId(id)) return null
    let changed: Stored | null
    try {
      changed = await this.db.models.orders
        .findOneAndUpdate({ _id: id }, { $pull: { lines: { _id: lineId } } }, { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Order', error)
    }
    return changed === null ? null : toEntity(changed)
  }

  /** Adds an item to notes, and returns the row as it is then, or null when there is none. */
  async addNote(id: string, note: { _id?: string | null; text?: string | null; at?: Date | null }): Promise<Order | null> {
    if (!isObjectId(id)) return null
    let changed: Stored | null
    try {
      changed = await this.db.models.orders
        .findOneAndUpdate({ _id: id }, { $push: { notes: note } }, { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Order', error)
    }
    return changed === null ? null : toEntity(changed)
  }

  /** Removes an item from notes, and returns the row as it is then, or null when there is none. */
  async removeNote(id: string, noteId: string): Promise<Order | null> {
    if (!isObjectId(id)) return null
    let changed: Stored | null
    try {
      changed = await this.db.models.orders
        .findOneAndUpdate({ _id: id }, { $pull: { notes: { _id: noteId } } }, { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Order', error)
    }
    return changed === null ? null : toEntity(changed)
  }
}

/** Keeps orders rows in memory, for tests and for trying the services without a database. */
export class MemoryOrderRepository implements OrderRepository {
  private readonly rows = new Map<string, Order>()

  private visible(): Order[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Order | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows after the key `after`, by primary key, and the key to read the next page from. */
  async list(after: unknown[] | null = null, limit: number = 50): Promise<CursorPage<Order>> {
    const rows = this.visible().filter((row) => after === null || compareKeys(keyOf(row), after) > 0)
    const items = rows.slice(0, limit)
    return { items, next: rows.length > limit ? keyOf(items[items.length - 1]) : null }
  }

  /** The row with this year and number, or null. */
  async findByYearAndNumber(year: number, number: number): Promise<Order | null> {
    return this.visible().find((row) => row.year === year && row.number === number) ?? null
  }

  /** Rows with this customer, by primary key. */
  async listByCustomer(customer: string): Promise<Order[]> {
    return this.visible().filter((row) => row.customer === customer)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Order): Promise<Order> {
    if (entity.id === undefined) entity.id = randomBytes(12).toString('hex')
    if (entity.placedAt === undefined) entity.placedAt = new Date()
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Order): Promise<Order> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Order): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }

  /** Adds an item to lines, and returns the row as it is then, or null when there is none. */
  async addLine(id: string, line: { _id?: string | null; product: string; quantity: number; price: string; status?: string | null }): Promise<Order | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    row.lines = [...(row.lines ?? []), { _id: randomBytes(12).toString('hex'), ...line }]
    return row
  }

  /** Removes an item from lines, and returns the row as it is then, or null when there is none. */
  async removeLine(id: string, lineId: string): Promise<Order | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    row.lines = (row.lines ?? []).filter((item) => item._id !== lineId)
    return row
  }

  /** Adds an item to notes, and returns the row as it is then, or null when there is none. */
  async addNote(id: string, note: { _id?: string | null; text?: string | null; at?: Date | null }): Promise<Order | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    row.notes = [...(row.notes ?? []), { _id: randomBytes(12).toString('hex'), ...note }]
    return row
  }

  /** Removes an item from notes, and returns the row as it is then, or null when there is none. */
  async removeNote(id: string, noteId: string): Promise<Order | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    row.notes = (row.notes ?? []).filter((item) => item._id !== noteId)
    return row
  }
}

