/** Operations on orders: what each one checks before it writes. */
import { problems, type Rule } from '../documents.js'
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { OrderCreate, OrderRead, OrderUpdate } from './dtos.js'
import { Order } from './entity.js'
import type { CursorPage } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['number', 'year', 'customer', 'lines', 'notes'])

/** The rules of the documents and lists inside each one */
const DOCUMENTS = {
  lines: { items: { fields: { product: { required: true }, quantity: { required: true, min: 1 }, price: { required: true }, status: { values: ['pending', 'sent'] } } } },
  notes: { items: { fields: { text: {}, at: {} } } },
} satisfies Record<string, Rule>

/** Operations on orders. Each write runs in its own transaction. */
export class OrderService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "orders" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Order | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Order' })
    if (!creating) for (const name of Object.keys(values)) if (['id', 'placedAt'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.number
      if (value == null) {
        if (creating || 'number' in values) errors.push({ field: 'number', message: 'is required' })
      }
    }
    {
      const value = values.year
      if (value == null) {
        if (creating || 'year' in values) errors.push({ field: 'year', message: 'is required' })
      }
    }
    {
      const value = values.customer
      if (value == null) {
        if (creating || 'customer' in values) errors.push({ field: 'customer', message: 'is required' })
      } else {
        if (typeof value === 'string' && value.length > 24) errors.push({ field: 'customer', message: 'is longer than 24 characters' })
      }
    }
    {
      const value = values.lines
      if (value == null) {
        if (creating || 'lines' in values) errors.push({ field: 'lines', message: 'is required' })
      } else {
        errors.push(...problems(value, DOCUMENTS.lines, 'lines'))
      }
    }
    {
      const value = values.notes
      if (value != null) {
        errors.push(...problems(value, DOCUMENTS.notes, 'notes'))
      }
    }
    {
      const customer = 'customer' in values ? values.customer : current?.customer
      if (customer != null && (await uow.customers.findById(customer as string)) === null)
        errors.push({ field: 'customer', message: 'no Customer has this key' })
    }
    if (errors.length > 0) throw new ValidationFailedError('Order', errors)
  }

  /** Values that must be unique are not taken by another row. */
  private async checkUnique(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Order | null): Promise<void> {
    {
      const year = ('year' in values ? values.year : current?.year) as number | null | undefined
      const number = ('number' in values ? values.number : current?.number) as number | null | undefined
      if (year != null && number != null) {
        const other = await uow.orders.findByYearAndNumber(year, number)
        if (other !== null && (current === null || other.id !== current.id))
          throw new ConflictError('Order', 'year, number is already taken', ['year', 'number'])
      }
    }
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Order | null): Promise<void> {
    await this.validate(uow, values, current)
    await this.checkUnique(uow, values, current)
  }

  /** The Order with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: string): Promise<Order> {
    const entity = await uow.orders.findById(id)
    if (entity === null) throw new NotFoundError('Order', id)
    return entity
  }

  /** The Order as services return it. */
  private static read(entity: Order): OrderRead {
    return { id: entity.id, number: entity.number, year: entity.year, customer: entity.customer, lines: entity.lines, notes: entity.notes, placedAt: entity.placedAt }
  }

  /** Stores a new Order after checking it. */
  async createOrder(data: OrderCreate): Promise<OrderRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.orders.insert(Object.assign(new Order(), values))
      return OrderService.read(created)
    })
  }

  /** The Order with this key; NotFoundError when there is none. */
  async getOrder(id: string): Promise<OrderRead> {
    return OrderService.read(await this.find(this.uow, id))
  }

  /** A page of orders after the key `after`, by primary key. */
  async listOrders(after: unknown[] | null = null, limit = 50): Promise<CursorPage<OrderRead>> {
    const page = await this.uow.orders.list(after, limit)
    return { ...page, items: page.items.map((entity) => OrderService.read(entity)) }
  }

  /** Changes the given values of a Order. */
  async updateOrder(id: string, data: OrderUpdate): Promise<OrderRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.orders.update(current)
      return OrderService.read(updated)
    })
  }

  /** Deletes a Order. */
  async deleteOrder(id: string): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await uow.orders.delete(current)
    })
  }

  /** The Order with this year and number, or null. */
  async findOrderByYearAndNumber(year: number, number: number): Promise<OrderRead | null> {
    const entity = await this.uow.orders.findByYearAndNumber(year, number)
    return entity === null ? null : OrderService.read(entity)
  }

  /** The orders with this customer. */
  async listOrdersByCustomer(customer: string): Promise<OrderRead[]> {
    return (await this.uow.orders.listByCustomer(customer)).map((entity) => OrderService.read(entity))
  }

  /** Adds an item to lines. */
  async addLine(id: string, line: { _id?: string | null; product: string; quantity: number; price: string; status?: string | null }): Promise<OrderRead> {
    const errors = problems([line], DOCUMENTS.lines, 'lines')
    if (errors.length > 0) throw new ValidationFailedError('Order', errors)
    return this.uow.transaction(async (uow) => {
      await this.find(uow, id)
      const updated = await uow.orders.addLine(id, line)
      if (updated === null) throw new NotFoundError('Order', id)
      return OrderService.read(updated)
    })
  }

  /** Removes an item from lines, by its identifier. */
  async removeLine(id: string, lineId: string): Promise<OrderRead> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (!(current.lines ?? []).some((item) => item._id === lineId)) throw new NotFoundError('Line', lineId)
      const updated = await uow.orders.removeLine(id, lineId)
      if (updated === null) throw new NotFoundError('Order', id)
      return OrderService.read(updated)
    })
  }

  /** Adds an item to notes. */
  async addNote(id: string, note: { _id?: string | null; text?: string | null; at?: Date | null }): Promise<OrderRead> {
    const errors = problems([note], DOCUMENTS.notes, 'notes')
    if (errors.length > 0) throw new ValidationFailedError('Order', errors)
    return this.uow.transaction(async (uow) => {
      await this.find(uow, id)
      const updated = await uow.orders.addNote(id, note)
      if (updated === null) throw new NotFoundError('Order', id)
      return OrderService.read(updated)
    })
  }

  /** Removes an item from notes, by its identifier. */
  async removeNote(id: string, noteId: string): Promise<OrderRead> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (!(current.notes ?? []).some((item) => item._id === noteId)) throw new NotFoundError('Note', noteId)
      const updated = await uow.orders.removeNote(id, noteId)
      if (updated === null) throw new NotFoundError('Order', id)
      return OrderService.read(updated)
    })
  }
}

