/** Operations on products: what each one checks before it writes. */
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { CursorPage } from '../paging.js'
import type { ProductCreate, ProductRead, ProductUpdate } from './dtos.js'
import { Product } from './entity.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['sku', 'title', 'price', 'stock', 'reference', 'picture', 'related'])

/** Operations on products. Each write runs in its own transaction. */
export class ProductService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "products" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Product | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Product' })
    if (!creating) for (const name of Object.keys(values)) if (['id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.sku
      if (value == null) {
        if (creating || 'sku' in values) errors.push({ field: 'sku', message: 'is required' })
      }
    }
    {
      const value = values.title
      if (value == null) {
        if (creating || 'title' in values) errors.push({ field: 'title', message: 'is required' })
      }
    }
    {
      const value = values.price
      if (value == null) {
        if (creating || 'price' in values) errors.push({ field: 'price', message: 'is required' })
      }
    }
    {
      const value = values.stock
      if (value != null) {
        if (!(Number(value) >= 0)) errors.push({ field: 'stock', message: 'must be >= 0' })
      }
    }
    if (errors.length > 0) throw new ValidationFailedError('Product', errors)
  }

  /** Values that must be unique are not taken by another row. */
  private async checkUnique(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Product | null): Promise<void> {
    {
      const sku = ('sku' in values ? values.sku : current?.sku) as string | null | undefined
      if (sku != null) {
        const other = await uow.products.findBySku(sku)
        if (other !== null && (current === null || other.id !== current.id))
          throw new ConflictError('Product', 'sku is already taken', ['sku'])
      }
    }
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Product | null): Promise<void> {
    await this.validate(uow, values, current)
    await this.checkUnique(uow, values, current)
  }

  /** The Product with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: string): Promise<Product> {
    const entity = await uow.products.findById(id)
    if (entity === null) throw new NotFoundError('Product', id)
    return entity
  }

  /** The Product as services return it. */
  private static read(entity: Product): ProductRead {
    return { id: entity.id, sku: entity.sku, title: entity.title, price: entity.price, stock: entity.stock, reference: entity.reference, picture: entity.picture, related: entity.related }
  }

  /** Stores a new Product after checking it. */
  async createProduct(data: ProductCreate): Promise<ProductRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.products.insert(Object.assign(new Product(), values))
      return ProductService.read(created)
    })
  }

  /** The Product with this key; NotFoundError when there is none. */
  async getProduct(id: string): Promise<ProductRead> {
    return ProductService.read(await this.find(this.uow, id))
  }

  /** A page of products after the key `after`, by primary key. */
  async listProducts(after: unknown[] | null = null, limit = 50): Promise<CursorPage<ProductRead>> {
    const page = await this.uow.products.list(after, limit)
    return { ...page, items: page.items.map((entity) => ProductService.read(entity)) }
  }

  /** Changes the given values of a Product. */
  async updateProduct(id: string, data: ProductUpdate): Promise<ProductRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.products.update(current)
      return ProductService.read(updated)
    })
  }

  /** Deletes a Product. */
  async deleteProduct(id: string): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await uow.products.delete(current)
    })
  }

  /** The Product with this sku, or null. */
  async findProductBySku(sku: string): Promise<ProductRead | null> {
    const entity = await this.uow.products.findBySku(sku)
    return entity === null ? null : ProductService.read(entity)
  }

  /** Adds an item to related. */
  async addRelated(id: string, related: string): Promise<ProductRead> {
    return this.uow.transaction(async (uow) => {
      await this.find(uow, id)
      const updated = await uow.products.addRelated(id, related)
      if (updated === null) throw new NotFoundError('Product', id)
      return ProductService.read(updated)
    })
  }

  /** Removes an item from related, by its value. */
  async removeRelated(id: string, related: string): Promise<ProductRead> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (!(current.related ?? []).includes(related)) throw new NotFoundError('Related', related)
      const updated = await uow.products.removeRelated(id, related)
      if (updated === null) throw new NotFoundError('Product', id)
      return ProductService.read(updated)
    })
  }
}

