/** The repositories of every table, and the transaction of each service operation. Each service operation runs in `transaction()`: committed when it ends, rolled back when it fails. */
import type { ClientSession } from 'mongoose'
import { MemoryCountryRepository, MongoCountryRepository, type CountryRepository } from './country/repository.js'
import { MemoryCustomerRepository, MongoCustomerRepository, type CustomerRepository } from './customer/repository.js'
import type { Db } from './database.js'
import { MemoryOrderRepository, MongoOrderRepository, type OrderRepository } from './order/repository.js'
import { MemoryProductRepository, MongoProductRepository, type ProductRepository } from './product/repository.js'

/** What services depend on: a repository per table and a transaction. */
export interface UnitOfWork {
  readonly customers: CustomerRepository
  readonly products: ProductRepository
  readonly orders: OrderRepository
  readonly countries: CountryRepository
  /** Runs `work` with the repositories of the transaction; commits when it ends, rolls back when it throws. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T>
}

/** The repositories over one database and, when there is one, the session whose transaction every query runs in. */
export class MongoUnitOfWork implements UnitOfWork {
  readonly customers: CustomerRepository
  readonly products: ProductRepository
  readonly orders: OrderRepository
  readonly countries: CountryRepository

  constructor(
    readonly db: Db,
    readonly session: ClientSession | null = null,
  ) {
    this.customers = new MongoCustomerRepository(db, session)
    this.products = new MongoProductRepository(db, session)
    this.orders = new MongoOrderRepository(db, session)
    this.countries = new MongoCountryRepository(db, session)
  }

  /** Runs `work` in a transaction of its own, or in the one already open. MongoDB has transactions on replica sets only. */
  async transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T> {
    if (this.session) return work(this)
    const session = await this.db.connection.startSession()
    try {
      return await session.withTransaction(() => work(new MongoUnitOfWork(this.db, session)))
    } finally {
      await session.endSession()
    }
  }
}

/** The in-memory repositories, for tests and for trying the services without a database. */
export class MemoryUnitOfWork implements UnitOfWork {
  readonly customers = new MemoryCustomerRepository()
  readonly products = new MemoryProductRepository()
  readonly orders = new MemoryOrderRepository()
  readonly countries = new MemoryCountryRepository()

  /** Memory has no transactions: changes are kept as they are made. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T> {
    return work(this)
  }
}

