/** Rows for the tests: valid values for every column, and the rows they point to. */
import { Country } from '../src/country/entity.js'
import { Customer } from '../src/customer/entity.js'
import { Order } from '../src/order/entity.js'
import { Product } from '../src/product/entity.js'
import type { UnitOfWork } from '../src/unit-of-work.js'

/** A valid Customer that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newCustomer(n = 1, values: Partial<Customer> = {}): Customer {
  return Object.assign(new Customer(), { email: `email-${n}`, name: `name-${n}`, passwordHash: `passwordhash-${n}`, active: true, level: 'basic', address: { street: `street-${n}`, city: `city-${n}`, 'zip code': `zipcode-${n}`, location: { type: 'Point', coordinates: [] } }, tags: [], preferences: { theme: `theme-${n}`, newsletter: true }, extra: { n }, deletedAt: null, updatedAt: new Date(Date.UTC(2026, 0, (n % 28) + 1, 12, 0, 0)) }, values)
}

/** A stored Customer. */
export async function addCustomer(uow: UnitOfWork, n = 1): Promise<Customer> {
  return uow.customers.insert(newCustomer(n))
}

/** A valid Product that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newProduct(n = 1, values: Partial<Product> = {}): Product {
  return Object.assign(new Product(), { sku: `sku-${n}`, title: `title-${n}`, price: `${n % 10000}.50`, stock: n + 0.5, reference: `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`, picture: Buffer.from([n % 256]), related: [] }, values)
}

/** A stored Product. */
export async function addProduct(uow: UnitOfWork, n = 1): Promise<Product> {
  return uow.products.insert(newProduct(n))
}

/** A valid Order that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newOrder(n = 1, values: Partial<Order> = {}): Order {
  return Object.assign(new Order(), { number: n + 0.5, year: n + 0.5, lines: [{ product: n.toString(16).padStart(24, '0'), quantity: n + 0.5, price: `${n % 10000}.50`, status: 'pending' }], notes: [{ text: `text-${n}`, at: new Date(Date.UTC(2026, 0, (n % 28) + 1, 12, 0, 0)) }] }, values)
}

/** A stored Order, with the rows it points to. */
export async function addOrder(uow: UnitOfWork, n = 1): Promise<Order> {
  const parent0 = await addCustomer(uow, n)
  return uow.orders.insert(newOrder(n, { customer: parent0.id }))
}

/** A valid Country that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newCountry(n = 1, values: Partial<Country> = {}): Country {
  return Object.assign(new Country(), { _id: `id-${n}`, id: n + 0.5, name: `name-${n}` }, values)
}

/** A stored Country. */
export async function addCountry(uow: UnitOfWork, n = 1): Promise<Country> {
  return uow.countries.insert(newCountry(n))
}

